        aria-label="Toggle menu"
        @click="isOpen = !isOpen"
      >
        ☰
      </button>

      <button
        @click="router.push({ name: 'home' })"
        class="font-extrabold text-base md:text-lg text-white flex justify-center items-center gap-2 hover:opacity-80 transition-opacity"
      >
